effect.shader:
void main() {
    vec2 direction;

    if (radial) {
        // No modo radial o deslocamento aponta para fora do centro, o que imita
        // de verdade como uma lente real erra — o erro cresce nas bordas.
        vec2 fromCenter = acScreenNorm - vec2(0.5);
        direction = fromCenter * 2.0;
    } else {
        // Não chame a variável de `radians`: o nome sombrearia a função nativa
        // `radians()` já dentro do próprio inicializador, e não compila.
        float rad = radians(angle);
        direction = vec2(cos(rad), sin(rad));
    }

    // Em pixels da COMPOSIÇÃO: `acEscalaDePixel` converte para o buffer, e a prévia
    // reduzida (o Auto da tela, o play) fica do tamanho da exportação (0.516.0).
    vec2 offset = direction * (amount * acEscalaDePixel) * acTexelSize;

    // Só o alpha do canal central importa: os outros dois já estão deslocados e
    // usar o alpha deles produziria franjas transparentes na borda da camada.
    vec4 center = texture(inputImg, acScreenNorm);
    float r = texture(inputImg, acScreenNorm + offset).r;
    float b = texture(inputImg, acScreenNorm - offset).b;

    fragColor = vec4(r, center.g, b, center.a);
}
